"""Fleet-scaled TerraListen public console built on the live radio surface."""
# ruff: noqa: E501

from __future__ import annotations

from terrasatch.landing_v2 import build_landing_page as build_base_landing_page

_OLD_FLEET = '''<section class="card"><div class="title"><span>REGISTERED EDGE</span><b id="fleet-badge">PRIVATE</b></div><div class="rows"><div class="row"><span>Fleet</span><b id="fleet-summary" class="health unknown">ADMIN SIGN-IN</b></div><div class="row"><span>Device</span><b id="fleet-device">—</b></div><div class="row"><span>Hardware</span><b id="fleet-hardware">—</b></div><div class="row"><span>RX</span><b id="fleet-rx">—</b></div><div class="row"><span>TX</span><b id="fleet-tx">—</b></div><div class="row"><span>Mode</span><b id="fleet-mode">—</b></div></div><div class="fleet-detail" id="fleet-detail">Registered device state is session-protected. Sign into Admin to show heartbeat age, reported hardware, RX/TX capabilities and current Satchy policy.</div></section>'''

_NEW_FLEET = '''<section class="card fleet-card"><div class="title"><span>TERRASATCH NETWORK</span><b id="network-badge">LIVE</b></div><div class="network-primary"><span>REGISTERED NODES</span><div class="network-count"><b id="network-nodes">— / —</b><small id="network-capacity-label">LOADING</small></div><div class="capacity-track"><i id="network-capacity-bar"></i></div></div><div class="fleet-metrics"><div><span>ONLINE</span><b id="network-online">—</b></div><div><span>FIELD SITES</span><b id="network-sites">—</b></div><div><span>MEMBERS</span><b id="network-members">—</b></div><div><span>CAPACITY</span><b id="network-capacity">—</b></div></div><div class="network-health"><span>NETWORK HEALTH</span><b id="network-health" class="health unknown">CHECKING</b></div><div class="fleet-private"><div class="fleet-private-title"><span>PRIVATE FLEET DETAIL</span><b id="fleet-badge">SIGN IN</b></div><div class="fleet-primary" id="fleet-primary" hidden><div class="row"><span>Device</span><b id="fleet-device">—</b></div><div class="row"><span>Radio hardware</span><b id="fleet-hardware">—</b></div><div class="row"><span>RX</span><b id="fleet-rx">—</b></div><div class="row"><span>TX</span><b id="fleet-tx">—</b></div><div class="row"><span>Mode</span><b id="fleet-mode">—</b></div></div><div class="fleet-detail" id="fleet-detail">Public network totals are visible above. Sign in to Admin or the organization portal for tenant-scoped device details.</div></div><div class="fleet-links"><a href="/admin">SUPERADMIN FLEET</a><a href="/portal">ORGANIZATION PORTAL</a></div></section>'''

_EXTRA_STYLE = '''<style>
.network-primary{padding:10px 12px;border-bottom:1px solid var(--l);background:linear-gradient(90deg,rgba(244,122,32,.05),transparent)}.network-primary>span,.fleet-metrics span,.network-health span,.fleet-private-title span{display:block;color:var(--m2);font:800 7px var(--mono);letter-spacing:.09em}.network-count{display:flex;align-items:end;justify-content:space-between;gap:8px;margin-top:4px}.network-count b{font-size:17px;color:var(--t)}.network-count small{color:var(--m);font:800 7px var(--mono);letter-spacing:.06em}.capacity-track{height:4px;margin-top:8px;background:rgba(255,255,255,.06);border-radius:999px;overflow:hidden}.capacity-track i{display:block;width:0;height:100%;background:var(--green);transition:width .35s ease,background .2s ease}.capacity-track i.watch{background:var(--yellow)}.capacity-track i.near,.capacity-track i.paused{background:var(--red)}.fleet-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--l);border-bottom:1px solid var(--l)}.fleet-metrics>div{background:var(--p2);padding:7px 10px;min-width:0}.fleet-metrics b{display:block;margin-top:3px;font-size:10px;overflow-wrap:anywhere}.network-health{display:flex;align-items:center;justify-content:space-between;padding:8px 11px;border-bottom:1px solid var(--l)}.network-health b{font-size:8px}.fleet-private-title{display:flex;align-items:center;justify-content:space-between;padding:7px 11px;background:rgba(255,255,255,.018);border-bottom:1px solid var(--l)}.fleet-private-title b{color:var(--m);font:800 7px var(--mono);letter-spacing:.06em}.fleet-primary{padding:4px 0;border-bottom:1px solid var(--l)}.fleet-primary .row{padding-top:3px;padding-bottom:3px}.fleet-detail{padding:8px 11px;color:var(--m);font-size:8px;line-height:1.45}.fleet-links{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--l)}.fleet-links a{padding:8px 10px;text-align:center;color:var(--m);text-decoration:none;font:800 7px var(--mono);letter-spacing:.06em}.fleet-links a+a{border-left:1px solid var(--l)}.fleet-links a:hover{color:var(--o2);background:var(--os)}
</style>'''

_EXTRA_SCRIPT = '''<script>
(()=>{const q=id=>document.getElementById(id);const set=(id,value,cls='')=>{const el=q(id);if(!el)return;el.textContent=String(value);if(cls)el.className=cls};const age=value=>value==null?'never reported':value<60?`${value}s ago`:value<3600?`${Math.floor(value/60)}m ago`:`${Math.floor(value/3600)}h ago`;const stateLabel=value=>({healthy:'HEALTHY',capacity_watch:'CAPACITY WATCH',near_capacity:'NEAR CAPACITY',registration_paused:'REGISTRATION PAUSED'}[value]||'UNKNOWN');const stateClass=value=>value==='healthy'?'healthy':value==='capacity_watch'?'degraded':value==='near_capacity'||value==='registration_paused'?'unhealthy':'unknown';async function fetchNetwork(){try{const r=await fetch('/api/v1/network/status',{cache:'no-store'});if(r.ok)return await r.json()}catch(_){}return null}async function fetchFleet(){for(const url of ['/admin/fleet-status','/portal/fleet-status']){try{const r=await fetch(url,{cache:'no-store',credentials:'same-origin'});if(r.ok)return await r.json()}catch(_){}}return null}function setSignal(device){const signal=q('radio-signal'),state=q('listen-state'),label=q('listen-label'),source=q('signal-source');if(!signal||!state||!label||!source||!device)return;signal.dataset.edge=device.health||'standby';const online=device.health==='online',stale=device.health==='stale';state.textContent=online?'EDGE ONLINE':stale?'EDGE STALE':String(device.health||'standby').toUpperCase();state.className=online?'green':stale?'yellow':device.health==='offline'?'red':'orange';label.textContent=online?'LISTENING · EDGE HEARTBEAT LIVE':stale?'LISTENING · HEARTBEAT STALE':'LISTENING · WAITING FOR EDGE';source.textContent=device.name||'REGISTERED EDGE'}async function refreshNetwork(){const p=await fetchNetwork();if(!p){set('network-badge','STATUS');set('network-health','UNAVAILABLE','health unknown');return}const limits=p.limits||{},util=p.utilization||{},state=p.capacity_state||'unknown',pct=Number(util.capacity_percent||0);set('network-badge','LIVE');set('network-nodes',`${p.registered_nodes||0} / ${limits.nodes||'—'}`);set('network-online',p.online_nodes||0,(p.online_nodes||0)?'green':'');set('network-sites',p.field_sites||0);set('network-members',`${p.members||0} / ${limits.members||'—'}`);set('network-capacity',`${pct}%`);set('network-capacity-label',stateLabel(state));set('network-health',stateLabel(state),`health ${stateClass(state)}`);const bar=q('network-capacity-bar');if(bar){bar.style.width=`${Math.min(100,Math.max(0,pct))}%`;bar.className=state==='capacity_watch'?'watch':state==='near_capacity'?'near':state==='registration_paused'?'paused':''}}async function refreshFleet(){const p=await fetchFleet(),primary=q('fleet-primary');if(!p){if(primary)primary.hidden=true;set('fleet-badge','SIGN IN');const detail=q('fleet-detail');if(detail)detail.textContent='Public network totals are visible above. Sign in to Admin or the organization portal for tenant-scoped device details.';return}const s=p.summary||{},devices=p.devices||[];set('fleet-badge',p.organization_name?'ORG':'LIVE');const device=devices.find(x=>x.health==='online')||devices.find(x=>x.health==='stale')||devices[0];if(!device){if(primary)primary.hidden=true;const detail=q('fleet-detail');if(detail)detail.textContent=`Signed in · ${s.total||0} registered device(s) · no active priority Edge`;return}if(primary)primary.hidden=false;set('fleet-device',device.name||'Edge');set('fleet-hardware',device.primary_hardware||device.hardware||'No radio hardware reported');set('fleet-rx',device.rx_supported?(device.rx_enabled?'SUPPORTED · ON':'SUPPORTED · OFF'):'UNAVAILABLE',device.rx_supported?'green':'');set('fleet-tx',device.tx_supported?(device.tx_enabled?'SUPPORTED · ARMED':'SUPPORTED · OFF'):'UNAVAILABLE',device.tx_supported?(device.tx_enabled?'yellow':'blue'):'');set('fleet-mode',device.mode||'IDLE');const detail=q('fleet-detail');if(detail)detail.innerHTML=`<strong>${String(device.health||'unknown').toUpperCase()}</strong> · last heartbeat ${age(device.age_seconds)} · ${s.total||devices.length} private fleet device(s) · ${device.hardware_count||0} host hardware item(s)`;setSignal(device)}refreshNetwork();refreshFleet();setInterval(refreshNetwork,30000);setInterval(refreshFleet,10000)})();
</script>'''


def build_landing_page(*, environment: str, deployment: str, version: str, docs_enabled: bool) -> str:
    html = build_base_landing_page(
        environment=environment,
        deployment=deployment,
        version=version,
        docs_enabled=docs_enabled,
    )
    html = html.replace(_OLD_FLEET, _NEW_FLEET, 1)
    html = html.replace(
        '<a href="/admin">Admin</a>',
        '<a href="/portal">Portal</a><a href="/admin">Admin</a>',
        1,
    )
    html = html.replace("</head>", _EXTRA_STYLE + "</head>", 1)
    html = html.replace("</body>", _EXTRA_SCRIPT + "</body>", 1)
    return html
